(()=>{const $=s=>document.querySelector(s);let recorder,streams=[],chunks=[],url,context;const mp4Mime=['video/mp4;codecs=avc1.42001E,mp4a.40.2','video/mp4;codecs=avc1.42E01E,mp4a.40.2','video/mp4'].find(v=>window.MediaRecorder&&MediaRecorder.isTypeSupported(v));const start=$('#start'),pause=$('#pause'),stop=$('#stop'),status=$('#status'),preview=$('video');function cleanup(){streams.forEach(s=>s.getTracks().forEach(t=>t.stop()));streams=[];if(context){context.close();context=null}start.disabled=false;pause.disabled=true;stop.disabled=true}if(!window.isSecureContext||!navigator.mediaDevices?.getDisplayMedia){start.disabled=true;status.textContent='屏幕录制需要 HTTPS 或本机 localhost。域名启用 HTTPS 后可直接使用；当前可以下载完整桌面版。'}if(!mp4Mime){start.disabled=true;status.textContent='当前浏览器不支持直接录制 MP4。请使用较新版本的 Chrome / Edge，或下载完整桌面版。'}else if(!start.disabled){status.textContent='已就绪 · MP4 输出，开始后选择要共享的画面。'}start.onclick=async()=>{start.disabled=true;$('#download').hidden=true;chunks=[];try{const screen=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:30},audio:$('#system').checked});streams.push(screen);if($('#mic').checked){const mic=await navigator.mediaDevices.getUserMedia({audio:true});streams.push(mic)}let stream=screen;const audioTracks=streams.flatMap(s=>s.getAudioTracks());if(audioTracks.length>1){context=new AudioContext();const dest=context.createMediaStreamDestination();for(const t of audioTracks){context.createMediaStreamSource(new MediaStream([t])).connect(dest)}stream=new MediaStream([...screen.getVideoTracks(),...dest.stream.getAudioTracks()])}else if(audioTracks.length===1){stream=new MediaStream([...screen.getVideoTracks(),audioTracks[0]])}preview.srcObject=screen;preview.controls=false;preview.muted=true;preview.play();const mime=mp4Mime;if(!mime)throw Error('当前浏览器无法录制 MP4');recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{if(url)URL.revokeObjectURL(url);const type=recorder.mimeType;url=URL.createObjectURL(new Blob(chunks,{type}));preview.srcObject=null;preview.src=url;preview.controls=true;preview.muted=false;const a=$('#download');a.href=url;a.download='AIONE1-recording-'+new Date().toISOString().replace(/[:.]/g,'-')+'.mp4';a.hidden=false;status.textContent='录制已完成，预览后点击下载保存。关闭页面前请保存文件。';cleanup()};screen.getVideoTracks()[0].onended=()=>{if(recorder?.state!=='inactive')recorder.stop()};recorder.start(1000);pause.disabled=false;stop.disabled=false;pause.textContent='暂停';status.textContent='正在录制。音频是否可用取决于浏览器与共享目标。'}catch(e){cleanup();status.textContent=e.name==='NotAllowedError'?'未授予共享或麦克风权限，录制未开始。':'无法开始录制：'+e.message}};pause.onclick=()=>{if(recorder.state==='recording'){recorder.pause();pause.textContent='继续';status.textContent='录制已暂停'}else if(recorder.state==='paused'){recorder.resume();pause.textContent='暂停';status.textContent='正在录制'}};stop.onclick=()=>{if(recorder&&recorder.state!=='inactive')recorder.stop()};window.addEventListener('beforeunload',()=>{streams.forEach(s=>s.getTracks().forEach(t=>t.stop()));if(url)URL.revokeObjectURL(url)})})();